package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.JsonGenerationException;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JsonGenerator.writeEmbeddedObject
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen0Test {

    private JsonGenerator jsonGenerator;

    @Before
    public void setUp() {
        // Since JsonGenerator is abstract, we use Mockito to create a mock instance
        // and spy on it to test the real implementation of writeEmbeddedObject
        jsonGenerator = Mockito.spy(mock(JsonGenerator.class));
    }

    /**
     * Tests that passing null does nothing and returns without exception.
     * Covers: if (object == null) branch.
     */
    @Test
    public void testWriteEmbeddedObject_Null() throws IOException {
        jsonGenerator.writeEmbeddedObject(null);

        // Verify that no other methods were called (specifically writeBinary)
        verify(jsonGenerator, never()).writeBinary(any(byte[].class));
        verify(jsonGenerator, never()).writeBinary(any(Base64Variant.class), any(byte[].class), anyInt(), anyInt());
    }

    /**
     * Tests that passing a byte array calls the writeBinary method.
     * Covers: if (object instanceof byte[]) branch.
     */
    @Test
    public void testWriteEmbeddedObject_ByteArray() throws IOException {
        byte[] data = new byte[]{0x01, 0x02, 0x03};

        jsonGenerator.writeEmbeddedObject(data);

        // Verify that writeBinary(byte[]) was called exactly once with the correct data
        verify(jsonGenerator, times(1)).writeBinary(data);
    }

    /**
     * Tests that passing an unsupported object type throws a JsonGenerationException.
     * Covers: the final throw statement (unsupported type).
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_UnsupportedType() throws IOException {
        Object unsupportedObject = "I am a String, not a byte array";

        try {
            jsonGenerator.writeEmbeddedObject(unsupportedObject);
        } catch (JsonGenerationException e) {
            // Verify exception message contains the class name as per implementation
            if (!e.getMessage().contains(unsupportedObject.getClass().getName())) {
                throw e;
            }
            throw e;
        }
    }

    /**
     * Tests that passing an unsupported object type throws the exception and 
     * verifies the exception contains the correct context (this).
     */
    @Test
    public void testWriteEmbeddedObject_ExceptionDetails() throws IOException {
        Object unsupportedObject = 123; // Integer

        try {
            jsonGenerator.writeEmbeddedObject(unsupportedObject);
        } catch (JsonGenerationException e) {
            // The implementation passes 'this' to the exception constructor
            // We can't easily check the 'this' reference inside the exception via standard API,
            // but we check the message content.
            String expectedMsgPart = unsupportedObject.getClass().getName();
            assert e.getMessage().contains(expectedMsgPart);
            return;
        }

        org.junit.Assert.fail("Expected JsonGenerationException was not thrown");
    }
}
